"""Ereignis-Router: Ein Pulse verzweigt und ruft eine zweite Extension.

Enabled ist der Guard, Route entscheidet den Zweig. Parameter sind Settings;
_events und _branch sind fluechtiger Runtime-State. Keine Arbeit pro Frame.
"""
CustomParHelper = next(d for d in me.docked if 'ExtUtils' in d.tags).mod('CustomParHelper').CustomParHelper


class BranchLabExt:
    def __init__(self, ownerComp: COMP) -> None:
        self.ownerComp = ownerComp
        CustomParHelper.Init(self, ownerComp, enable_properties=True,
                             enable_callbacks=True, enable_parGroups=True, enable_seq=True)
        self._events: int = 0
        self._branch: str = 'bereit'

    def onInitTD(self) -> None:
        self.Reset()

    def onDestroyTD(self) -> None:
        """Keine Runs, Listener oder Frame-Callbacks vorhanden."""

    def onParFire(self) -> None:
        self.RouteEvent()

    def onParReset(self) -> None:
        self.Reset()

    @property
    def Events(self) -> int:
        return self._events

    @property
    def Branch(self) -> str:
        return self._branch

    def RouteEvent(self) -> None:
        """Guard -> Route -> Aufruf einer anderen Extension -> Status."""
        self._events += 1
        if not self.evalEnabled:
            self._branch = 'blocked'
            self.evalStatus = 'BLOCKED: Enabled ist aus; ApplyPreset wurde nicht gerufen.'
            return
        if self.evalRoute == 'warm':
            self._warm()
        elif self.evalRoute == 'cool':
            self._cool()
        else:
            self._neutral()

    def _warm(self) -> None:
        self._send('warm', 0)

    def _cool(self) -> None:
        self._send('cool', 1)

    def _neutral(self) -> None:
        self._send('neutral', 2)

    def _send(self, name: str, route: int) -> None:
        # Die Extension wird bei jedem Aufruf frisch am COMP aufgeloest.
        color = self.ownerComp.op('ColorEngine').ApplyPreset(name, float(self.evalIntensity))
        if color is None:
            self._branch = 'invalid'
            self.evalStatus = 'INVALID: Palette pruefen; die bisherige Farbe bleibt.'
            return
        self._branch = name
        control = self.ownerComp.op('control')
        control.par.const0value = float(self.evalIntensity)
        control.par.const1value = route
        self.evalStatus = f'{name.upper()}: Ereignis {self._events}; Farbe {color}'

    def Reset(self) -> None:
        self.evalEnabled = True
        self.evalRoute = 'warm'
        self.evalIntensity = 0.8
        self.evalSoftness = 12.0
        self._events = 0
        self._branch = 'bereit'
        self.ownerComp.op('ColorEngine').ApplyPreset('warm', 0.8)
        self.ownerComp.op('control').par.const0value = 0.8
        self.ownerComp.op('control').par.const1value = 0
        self.evalStatus = 'Bereit: Route waehlen und Fire druecken.'

